SET local check_function_bodies = off;

CREATE TABLE "public"."ad_claim" (
  "id"         bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id"    uuid                     NOT NULL,
  "ad_id"      uuid                     NOT NULL,
  "claimed_at" timestamp with time zone DEFAULT now(),
  CONSTRAINT "ad_claim_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."ad_claim"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."advert" (
  "id"            uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "created_by"    uuid,
  "title"         text                     NOT NULL,
  "image_url"     text,
  "link_url"      text,
  "active"        boolean                  NOT NULL DEFAULT true,
  "created_at"    timestamp with time zone NOT NULL DEFAULT now(),
  "reward_amount" integer                  NOT NULL DEFAULT 0,
  CONSTRAINT "advert_pkey" PRIMARY KEY (id),
  CONSTRAINT "advert_reward_amount_check" CHECK ((reward_amount >= 0))
);

ALTER TABLE "public"."advert"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."balance_log" (
  "id"         bigint                   GENERATED ALWAYS AS IDENTITY NOT NULL,
  "user_id"    uuid,
  "delta"      integer                  NOT NULL,
  "reason"     text                     NOT NULL,
  "admin_id"   uuid,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "balance_log_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."balance_log"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."chat_message" (
  "id"         bigint                   GENERATED ALWAYS AS IDENTITY NOT NULL,
  "table_id"   uuid                     NOT NULL,
  "user_id"    uuid,
  "body"       text                     NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "chat_message_body_check" CHECK (((length(body) >= 1) AND (length(body) <= 500))),
  CONSTRAINT "chat_message_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."chat_message"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."event" (
  "id"         uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "name"       text                     NOT NULL,
  "multiplier" numeric(4,2)             NOT NULL DEFAULT 2,
  "expires_at" timestamp with time zone NOT NULL,
  "created_by" uuid,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "event_multiplier_check" CHECK (((multiplier > (0)::numeric) AND (multiplier <= (10)::numeric))),
  CONSTRAINT "event_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."event"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."friendship" (
  "id"          uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "sender_id"   uuid                     NOT NULL,
  "receiver_id" uuid                     NOT NULL,
  "status"      integer                  NOT NULL DEFAULT 0,
  "created_at"  timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"  timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "friendship_check" CHECK ((sender_id <> receiver_id)),
  CONSTRAINT "friendship_not_self" CHECK ((sender_id <> receiver_id)),
  CONSTRAINT "friendship_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."friendship"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."match_log" (
  "id"              uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "match_id"        uuid                     NOT NULL,
  "user_id"         uuid,
  "action_type"     integer                  NOT NULL,
  "amount"          integer                  NOT NULL DEFAULT 0,
  "cards_discarded" integer,
  "created_at"      timestamp with time zone NOT NULL DEFAULT now(),
  "seat_number"     integer,
  CONSTRAINT "match_log_amount_check" CHECK ((amount >= 0)),
  CONSTRAINT "match_log_cards_discarded_check" CHECK (((cards_discarded >= 0) AND (cards_discarded <= 5))),
  CONSTRAINT "match_log_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."match_log"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."match_players" (
  "match_id"     uuid                     NOT NULL,
  "seat_number"  integer                  NOT NULL,
  "user_id"      uuid,
  "bot_name"     text,
  "net_result"   integer                  NOT NULL DEFAULT 0,
  "hand_rank"    text,
  "hand_history" jsonb,
  "created_at"   timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "match_players_pkey" PRIMARY KEY (match_id, seat_number)
);

ALTER TABLE "public"."match_players"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."match" (
  "id"           uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "table_id"     uuid                     NOT NULL,
  "match_number" integer                  NOT NULL,
  "pot"          integer                  NOT NULL DEFAULT 0,
  "winner_id"    uuid,
  "started_at"   timestamp with time zone NOT NULL DEFAULT now(),
  "ended_at"     timestamp with time zone,
  "dealer_seat"  integer,
  CONSTRAINT "match_dealer_seat_check" CHECK ((dealer_seat >= 0)),
  CONSTRAINT "match_match_number_unique" UNIQUE (table_id, match_number),
  CONSTRAINT "match_pkey" PRIMARY KEY (id),
  CONSTRAINT "match_pot_check" CHECK ((pot >= 0))
);

ALTER TABLE "public"."match"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."shop_item" (
  "id"         uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "name"       text                     NOT NULL,
  "cost"       integer                  NOT NULL,
  "asset_url"  text,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "item_type"  text,
  CONSTRAINT "shop_item_cost_check" CHECK ((cost >= 0)),
  CONSTRAINT "shop_item_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."shop_item"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."support_ticket" (
  "id"         bigint                   GENERATED ALWAYS AS IDENTITY NOT NULL,
  "user_id"    uuid,
  "body"       text                     NOT NULL,
  "status"     text                     NOT NULL DEFAULT 'open'::text,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "support_ticket_body_check" CHECK (((length(body) >= 1) AND (length(body) <= 2000))),
  CONSTRAINT "support_ticket_pkey" PRIMARY KEY (id),
  CONSTRAINT "support_ticket_status_valid" CHECK ((status = ANY (ARRAY['open'::text, 'resolved'::text])))
);

ALTER TABLE "public"."support_ticket"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."table_players" (
  "table_id"    uuid                     NOT NULL,
  "user_id"     uuid                     NOT NULL,
  "seat_number" integer                  NOT NULL,
  "stack"       integer                  NOT NULL DEFAULT 0,
  "joined_at"   timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "one_player_per_seat" UNIQUE (table_id, seat_number),
  CONSTRAINT "table_players_pkey" PRIMARY KEY (table_id, user_id),
  CONSTRAINT "table_players_seat_number_check" CHECK ((seat_number >= 0)),
  CONSTRAINT "table_players_stack_check" CHECK ((stack >= 0))
);

ALTER TABLE "public"."table_players"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."table" (
  "id"                  uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "name"                text                     NOT NULL,
  "host_id"             uuid,
  "variant"             text                     NOT NULL DEFAULT 'five_card_draw'::text,
  "max_players"         integer                  NOT NULL DEFAULT 6,
  "buy_in"              integer                  NOT NULL,
  "status"              integer                  NOT NULL DEFAULT 0,
  "created_at"          timestamp with time zone NOT NULL DEFAULT now(),
  "minimum_bet"         integer                  NOT NULL DEFAULT 0,
  "ante"                integer                  NOT NULL DEFAULT 0,
  "bot_count"           smallint                 NOT NULL DEFAULT 0,
  "raise_every_matches" smallint,
  "raise_pct"           smallint,
  "updated_at"          timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "bots_fit" CHECK ((bot_count < max_players)),
  CONSTRAINT "table_ante_check" CHECK ((ante >= 0)),
  CONSTRAINT "table_bot_count_check" CHECK ((bot_count >= 0)),
  CONSTRAINT "table_buy_in_check" CHECK ((buy_in > 0)),
  CONSTRAINT "table_max_players_check" CHECK (((max_players >= 2) AND (max_players <= 6))),
  CONSTRAINT "table_minimum_bet_check" CHECK ((minimum_bet >= 0)),
  CONSTRAINT "table_pkey" PRIMARY KEY (id),
  CONSTRAINT "table_raise_every_matches_check" CHECK ((raise_every_matches >= 1)),
  CONSTRAINT "table_raise_pct_check" CHECK (((raise_pct >= 1) AND (raise_pct <= 100)))
);

ALTER TABLE "public"."table"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."user_inventory" (
  "user_id"     uuid                     NOT NULL,
  "item_id"     uuid                     NOT NULL,
  "acquired_at" timestamp with time zone NOT NULL DEFAULT now(),
  "is_equipped" boolean                  NOT NULL DEFAULT false,
  CONSTRAINT "user_inventory_pkey" PRIMARY KEY (user_id, item_id)
);

ALTER TABLE "public"."user_inventory"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."user" (
  "id"                   uuid                     NOT NULL,
  "username"             text                     NOT NULL,
  "chip_balance"         integer                  NOT NULL DEFAULT 1000,
  "role"                 integer                  NOT NULL DEFAULT 0,
  "created_at"           timestamp with time zone NOT NULL DEFAULT now(),
  "last_daily_reward_at" timestamp with time zone,
  "is_top_player"        boolean                  NOT NULL DEFAULT false,
  "avatar_url"           text,
  "settings"             jsonb                    NOT NULL DEFAULT '{}'::jsonb,
  "current_streak"       integer                  NOT NULL DEFAULT 0,
  "is_guest"             boolean                  NOT NULL DEFAULT false,
  CONSTRAINT "user_chip_balance_check" CHECK ((chip_balance >= 0)),
  CONSTRAINT "user_current_streak_check" CHECK ((current_streak >= 0)),
  CONSTRAINT "user_pkey" PRIMARY KEY (id),
  CONSTRAINT "user_username_check" CHECK (((char_length(username) >= 3) AND (char_length(username) <= 20))),
  CONSTRAINT "user_username_key" UNIQUE (username)
);

ALTER TABLE "public"."user"
  ENABLE ROW LEVEL SECURITY;

