CREATE UNIQUE INDEX ad_claim_once_a_day ON public.ad_claim USING btree (user_id, ad_id, (((claimed_at AT TIME ZONE 'utc'::text))::date));

CREATE INDEX balance_log_user_idx ON public.balance_log USING btree (user_id, id DESC);

CREATE INDEX chat_message_table_idx ON public.chat_message USING btree (table_id, id DESC);

CREATE UNIQUE INDEX friendship_pair_key ON public.friendship USING btree (LEAST(sender_id, receiver_id), GREATEST(sender_id, receiver_id));

CREATE UNIQUE INDEX friendship_pair_unique ON public.friendship USING btree (LEAST(sender_id, receiver_id), GREATEST(sender_id, receiver_id));

CREATE INDEX friendship_receiver_idx ON public.friendship USING btree (receiver_id);

CREATE INDEX friendship_sender_idx ON public.friendship USING btree (sender_id);

CREATE INDEX match_log_match_idx ON public.match_log USING btree (match_id, created_at);

CREATE INDEX match_players_user_idx ON public.match_players USING btree (user_id, created_at DESC);

CREATE INDEX round_action_round_idx ON public.match_log USING btree (match_id);

CREATE INDEX table_player_user_idx ON public.table_players USING btree (user_id);

CREATE INDEX table_players_user_idx ON public.table_players USING btree (user_id);

CREATE INDEX user_leaderboard_idx ON public."user" USING btree (chip_balance DESC)
  WHERE (NOT is_guest);

CREATE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW
  EXECUTE FUNCTION public.handle_new_user();

CREATE TRIGGER friendship_updated_at
  BEFORE UPDATE ON public.friendship
  FOR EACH ROW
  WHEN ((old.* IS DISTINCT FROM new.*))
  EXECUTE FUNCTION public.set_updated_at();

CREATE TRIGGER support_ticket_updated_at
  BEFORE UPDATE ON public.support_ticket
  FOR EACH ROW
  WHEN ((old.* IS DISTINCT FROM new.*))
  EXECUTE FUNCTION public.set_updated_at();

CREATE TRIGGER table_updated_at
  BEFORE UPDATE ON public."table"
  FOR EACH ROW
  WHEN ((old.* IS DISTINCT FROM new.*))
  EXECUTE FUNCTION public.set_updated_at();

CREATE POLICY "see your own ad claims" ON "public"."ad_claim"
  FOR SELECT
  TO "authenticated"
  USING ((user_id = auth.uid()));

CREATE POLICY "see your own balance history" ON "public"."balance_log"
  FOR SELECT
  TO "authenticated"
  USING ((user_id = auth.uid()));

CREATE POLICY "read chat of a room you sit in" ON "public"."chat_message"
  FOR SELECT
  TO "authenticated"
  USING ((EXISTS ( SELECT 1
   FROM public.table_players tp
  WHERE ((tp.table_id = chat_message.table_id) AND (tp.user_id = auth.uid())))));

CREATE POLICY "send chat to a room you sit in" ON "public"."chat_message"
  FOR INSERT
  TO "authenticated"
  WITH CHECK (((user_id = auth.uid()) AND (EXISTS ( SELECT 1
   FROM public.table_players tp
  WHERE ((tp.table_id = chat_message.table_id) AND (tp.user_id = auth.uid()))))));

CREATE POLICY "read active events" ON "public"."event"
  FOR SELECT
  TO "authenticated"
  USING ((expires_at > now()));

CREATE POLICY "see your own match results" ON "public"."match_players"
  FOR SELECT
  TO "authenticated"
  USING ((user_id = auth.uid()));

CREATE POLICY "file a ticket" ON "public"."support_ticket"
  FOR INSERT
  TO "authenticated"
  WITH CHECK ((user_id = auth.uid()));

CREATE POLICY "see your own tickets" ON "public"."support_ticket"
  FOR SELECT
  TO "authenticated"
  USING ((user_id = auth.uid()));

CREATE EVENT TRIGGER "ensure_rls"
  ON ddl_command_end
  WHEN TAG IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
  EXECUTE FUNCTION "public"."rls_auto_enable"();

